import {DataTable} from '@primer/react/experimental'
import type {CustomPropertyValue} from '../types'
import {Link} from '@primer/react'

type ValuesTableProps = {
  data: CustomPropertyValue[]
  source: string
  getDefinitionDetailsPath: (source: string, property: string) => string
}

export const ValuesTable = ({data, source, getDefinitionDetailsPath}: ValuesTableProps) => {
  return (
    <DataTable
      data={data}
      columns={[
        {
          header: 'Property',
          field: 'property',
          renderCell: ({property}) => <Link href={getDefinitionDetailsPath(source, property)}>{property}</Link>,
        },
        {header: 'Value', field: 'value'},
      ]}
    />
  )
}
