type DefinitionListFieldProps = {
  label: string
  values: string[] | null
}

export const DefinitionListField = ({label, values}: DefinitionListFieldProps) => {
  if (!values || values.length === 0) return null

  return (
    <div>
      <span>
        <strong>{label}:</strong>
      </span>
      <div className="d-flex flex-column ml-2">
        {values.map(value => (
          <span key={value}>{value}</span>
        ))}
      </div>
    </div>
  )
}
